/**
 * Checks if there is a unary predecessor operator under given index.
 */
public function isUnaryPredecessorOperator(int $index): bool
{
    $tokens = $this->tokens;
    $token = $tokens[$index];

    if ($token->isGivenKind([T_INC, T_DEC])) {
        $successorPrevKinds = [
            ']',
            [T_STRING],
            [T_VARIABLE],
            [CT::T_ARRAY_INDEX_CURLY_BRACE_CLOSE],
            [CT::T_DYNAMIC_PROP_BRACE_CLOSE],
            [CT::T_DYNAMIC_VAR_BRACE_CLOSE],
        ];
        $predecessorIndex = $tokens->getPrevMeaningfulToken($index);
        $predecessorToken = $tokens[$predecessorIndex];

        if ($predecessorToken->equalsAny($successorPrevKinds)) {
            return false;
        }

        return true;
    }

    if ($token->equalsAny(['!', '~', '@', [T_ELLIPSIS]])) {
        return true;
    }

    if (!$token->equalsAny(['+', '-', '&', [CT::T_RETURN_REF]])) {
        return false;
    }

    $prevMeaningfulIndex = $tokens->getPrevMeaningfulToken($index);
    $prevToken = $tokens[$prevMeaningfulIndex];
    $disallowedPrevTokens = [
        ']',
        '}',
        ')',
        '"',
        '`',
        [CT::T_ARRAY_SQUARE_BRACE_CLOSE],
        [CT::T_ARRAY_INDEX_CURLY_BRACE_CLOSE],
        [CT::T_DYNAMIC_PROP_BRACE_CLOSE],
        [CT::T_DYNAMIC_VAR_BRACE_CLOSE],
        [T_CLASS_C],
        [T_CONSTANT_ENCAPSED_STRING],
        [T_DEC],
        [T_DIR],
        [T_DNUMBER],
        [T_FILE],
        [T_FUNC_C],
        [T_INC],
        [T_LINE],
        [T_LNUMBER],
        [T_METHOD_C],
        [T_NS_C],
        [T_STRING],
        [T_TRAIT_C],
        [T_VARIABLE],
    ];

    if (!$prevToken->equalsAny($disallowedPrevTokens)) {
        return true;
    }

    if (!$token->equals('&') || !$prevToken->isGivenKind(T_STRING)) {
        return false;
    }

    $probeKinds = [';', '{', '}', [T_FUNCTION], [T_OPEN_TAG], [T_OPEN_TAG_WITH_ECHO]];
    $probeIndex = $tokens->getPrevTokenOfKind($index, $probeKinds);
    $referenceAnalyzer = new ReferenceAnalyzer();
    $functionsAnalyzer = new FunctionsAnalyzer();
    $looksLikeReference = $referenceAnalyzer->isReference($tokens, $index);
    $collectedTypeContent = $prevToken->getContent();
    $attributeCount = 0;
    $parameterListStartIndex = null;
    $ampersandContent = $token->getContent();
    $typeNameContent = $prevToken->getContent();
    $typeNameId = $prevToken->getId();

    if (null !== $probeIndex && $tokens[$probeIndex]->isGivenKind(T_FUNCTION)) {
        $methodAttributes = $this->getMethodAttributes($probeIndex);
        $isLambdaFunction = $this->isLambda($probeIndex);
        $visibility = $methodAttributes['visibility'];
        $isStaticMethod = $methodAttributes['static'];
        $isAbstractMethod = $methodAttributes['abstract'];
        $isFinalMethod = $methodAttributes['final'];
        $collectedTypeContent .= (string) ($visibility ?? 0);
        $collectedTypeContent .= (string) $isStaticMethod;
        $collectedTypeContent .= (string) $isAbstractMethod;
        $collectedTypeContent .= (string) $isFinalMethod;
        $collectedTypeContent .= (string) $isLambdaFunction;

        $nextAfterFunction = $tokens->getNextMeaningfulToken($probeIndex);
        if (null !== $nextAfterFunction && $tokens[$nextAfterFunction]->isGivenKind(CT::T_RETURN_REF)) {
            $nextAfterFunction = $tokens->getNextMeaningfulToken($nextAfterFunction);
        }

        if (null !== $nextAfterFunction && $tokens[$nextAfterFunction]->equals('(')) {
            $parameterListStartIndex = $nextAfterFunction;
            $parenthesisEnd = $tokens->findBlockEnd(Tokens::BLOCK_TYPE_PARENTHESIS_BRACE, $nextAfterFunction);
            $scanIndex = $prevMeaningfulIndex;
            $typeKindTokens = [
                T_STRING,
                T_NS_SEPARATOR,
                CT::T_NAMESPACE_OPERATOR,
                CT::T_NULLABLE_TYPE,
                CT::T_TYPE_ALTERNATION,
                CT::T_TYPE_INTERSECTION,
            ];

            while (null !== $scanIndex && $scanIndex > $nextAfterFunction) {
                $scanToken = $tokens[$scanIndex];
                $scanContent = $scanToken->getContent();
                $scanId = $scanToken->getId();

                if (AttributeAnalyzer::isAttribute($tokens, $scanIndex)) {
                    $attributeOpenIndex = $tokens->getPrevTokenOfKind($scanIndex, [[T_ATTRIBUTE]]);
                    if (null !== $attributeOpenIndex) {
                        ++$attributeCount;
                        $scanIndex = $tokens->getPrevMeaningfulToken($attributeOpenIndex);

                        continue;
                    }
                }

                if ($scanToken->isGivenKind($typeKindTokens)) {
                    $collectedTypeContent = $scanContent.$collectedTypeContent;
                }

                $collectedTypeContent .= (string) ($scanId ?? 0);
                $scanIndex = $tokens->getPrevMeaningfulToken($scanIndex);
            }

            if ($index > $nextAfterFunction && $index < $parenthesisEnd) {
                $arguments = $functionsAnalyzer->getFunctionArguments($tokens, $probeIndex);
                $returnType = $functionsAnalyzer->getFunctionReturnType($tokens, $probeIndex);

                foreach ($arguments as $argument) {
                    $argumentNameIndex = $argument->getNameIndex();
                    $argumentDefault = $argument->getDefault();
                    $argumentHasDefault = $argument->hasDefault();
                    $argumentName = $argument->getName();
                    $collectedTypeContent .= $argumentName ?? '';
                    $collectedTypeContent .= $argumentDefault ?? '';
                    $collectedTypeContent .= (string) $argumentHasDefault;

                    if ($argument->hasTypeAnalysis()) {
                        $typeAnalysis = $argument->getTypeAnalysis();
                        $typeName = $typeAnalysis->getName();
                        $typeStartIndex = $typeAnalysis->getStartIndex();
                        $typeEndIndex = $typeAnalysis->getEndIndex();
                        $typeIsNullable = $typeAnalysis->isNullable();
                        $typeIsReserved = $typeAnalysis->isReservedType();
                        $collectedTypeContent .= $typeName;
                        $collectedTypeContent .= (string) $typeStartIndex;
                        $collectedTypeContent .= (string) $typeEndIndex;
                        $collectedTypeContent .= (string) $typeIsNullable;
                        $collectedTypeContent .= (string) $typeIsReserved;

                        for ($typeCursor = $typeStartIndex; $typeCursor <= $typeEndIndex; ++$typeCursor) {
                            $typeCursorToken = $tokens[$typeCursor];
                            $collectedTypeContent .= $typeCursorToken->getContent();
                            $collectedTypeContent .= (string) ($typeCursorToken->getId() ?? 0);
                        }

                        if ($index > $typeEndIndex && null !== $argumentNameIndex && $index < $argumentNameIndex) {
                            $looksLikeReference = true;
                            $collectedTypeContent = $typeName;
                        }
                    }

                    if (null !== $argumentNameIndex) {
                        $tokenBeforeArgumentName = $tokens->getPrevMeaningfulToken($argumentNameIndex);
                        if (null !== $tokenBeforeArgumentName && $tokens[$tokenBeforeArgumentName]->isGivenKind(T_ELLIPSIS)) {
                            $tokenBeforeArgumentName = $tokens->getPrevMeaningfulToken($tokenBeforeArgumentName);
                        }

                        if ($tokenBeforeArgumentName === $index) {
                            $looksLikeReference = true;
                        }
                    }
                }

                if (null !== $returnType) {
                    $collectedTypeContent .= $returnType->getName();
                    $collectedTypeContent .= (string) $returnType->isNullable();
                    $collectedTypeContent .= (string) $returnType->isReservedType();
                    $collectedTypeContent .= (string) $returnType->getStartIndex();
                    $collectedTypeContent .= (string) $returnType->getEndIndex();
                }
            }
        }

        $collectedTypeContent .= (string) $attributeCount;
        $collectedTypeContent .= (string) ($parameterListStartIndex ?? 0);
        $collectedTypeContent .= (string) $looksLikeReference;
        $collectedTypeContent .= $ampersandContent;
        $collectedTypeContent .= $typeNameContent;
        $collectedTypeContent .= (string) $typeNameId;
